import{_ as i,o as a,c as t,a5 as s}from"./chunks/framework.BZzouRtU.js";const n="/study/images/graphics/gpu-queue-synchronization.svg",E=JSON.parse('{"title":"D3D12のキューをフェンスでつなぐ","description":"","frontmatter":{"title":"D3D12のキューをフェンスでつなぐ","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"graphics","summary":"COPY・DIRECT・COMPUTE間で処理結果を渡す。キュー側のSignalとWait、CPU側のフェンス操作、COMMON状態、最後の参照までの寿命を扱う。","aliases":["D3D12キュー間同期","GPU queue synchronization","queue fence","Signal","Wait","SetEventOnCompletion","COPY queue","async compute","非同期コンピュート"],"verification":"MicrosoftのD3D12 APIリファレンスとマルチエンジン同期ガイドに照合（2026-11-06）"}},"headers":[],"relativePath":"graphics/optimization/gpu-queue-synchronization.md","filePath":"graphics/optimization/gpu-queue-synchronization.md"}'),r={name:"graphics/optimization/gpu-queue-synchronization.md"};function o(d,e,c,h,l,p){return a(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="d3d12のキューをフェンスでつなぐ" tabindex="-1">D3D12のキューをフェンスでつなぐ <a class="header-anchor" href="#d3d12のキューをフェンスでつなぐ" aria-label="Permalink to &quot;D3D12のキューをフェンスでつなぐ&quot;">​</a></h1><p>テクスチャをCOPYキューで転送し、DIRECTキューの描画で使う場合を考えます。CPUは転送と描画を別々に提出できます。DIRECTキューには、テクスチャを読む命令の前にCOPYキューの完了を待つ命令を入れます。この依存関係を表す目印が<strong>フェンス</strong>です。アプリが指定した整数値で、あるキューがどこまで進んだかを追います。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/user-mode-heap-synchronization" target="_blank" rel="noreferrer">Microsoftのマルチエンジン同期ガイド</a></p><figure class="study-figure"><img src="'+n+`" alt="COPYキューはテクスチャのコピー後にcopyDoneを11へ進める。DIRECTキューは独立した描画を先に行い、copyDoneの11を待った後、転送したテクスチャを使って描画する。その後でdrawDoneを24へ進める。転送元はコピー完了後、転送先は最後の描画完了後に回収できる。" width="760" height="454" loading="lazy"><figcaption>COPYとDIRECTの間でテクスチャを引き渡す例。横方向は各キューの処理順を示します。<a href="/study/images/graphics/gpu-queue-synchronization.svg" target="_blank" rel="noopener noreferrer">キュー間同期の図を拡大</a></figcaption></figure><h2 id="キューの種類で記録できる命令が決まる" tabindex="-1">キューの種類で記録できる命令が決まる <a class="header-anchor" href="#キューの種類で記録できる命令が決まる" aria-label="Permalink to &quot;キューの種類で記録できる命令が決まる&quot;">​</a></h2><table tabindex="0"><thead><tr><th>キューの種類</th><th>提出するリストに記録できる主な処理</th></tr></thead><tbody><tr><td>DIRECT</td><td>描画、コンピュートシェーダーの実行、コピー</td></tr><tr><td>COMPUTE</td><td>コンピュートシェーダーの実行とコピー</td></tr><tr><td>COPY</td><td>バッファーやテクスチャのコピー</td></tr></tbody></table><p>種類はAPIで扱える命令の範囲を表します。複数のキューに独立した処理を提出すると、GPUの構成と負荷に応じて実行が重なる場合があります。CPU側でコマンドリストを複数スレッドから記録する場合にも、提出先は一つのDIRECTキューにできます。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/user-mode-heap-synchronization#copy-and-compute-command-lists" target="_blank" rel="noreferrer">Microsoftのキューの種類と対応する命令</a> · <a href="/study/graphics/optimization/parallel-command-recording.html">D3D12の並列コマンド記録</a></p><h2 id="どこで値を書き、どこで待つか" tabindex="-1">どこで値を書き、どこで待つか <a class="header-anchor" href="#どこで値を書き、どこで待つか" aria-label="Permalink to &quot;どこで値を書き、どこで待つか&quot;">​</a></h2><table tabindex="0"><thead><tr><th>API</th><th>フェンスに対する動作</th></tr></thead><tbody><tr><td><code>ID3D12CommandQueue::Signal</code></td><td>キューに通知を積む。先に提出した処理が終わり、通知の位置まで進むと指定値を書き込む。</td></tr><tr><td><code>ID3D12CommandQueue::Wait</code></td><td>キューに待ちを積む。フェンスが指定値以上になるまで、この待ちより後ろの処理を進めない。呼び出したCPUスレッドはその場で待たずに戻る。</td></tr><tr><td><code>ID3D12Fence::Signal</code></td><td>CPUからフェンスの値を直ちに更新する。GPU処理の完了を知らせる用途では、完了させるキューへ <code>Signal</code> を積む。</td></tr><tr><td><code>ID3D12Fence::SetEventOnCompletion</code></td><td>指定値への到達をCPU側のイベントで知らせる。そのイベントを <code>WaitForSingleObject</code> などで待つと、呼び出したCPUスレッドが待機する。</td></tr></tbody></table><p><code>SetEventOnCompletion</code> にNULLハンドルを渡すと、呼び出し自体が到達まで待ちます。CPUが待たずに完了を調べるには <code>GetCompletedValue</code> を使います。デバイスが取り外された場合、このメソッドは <code>UINT64_MAX</code> を返します。通常の到達判定とは分けてエラーとして処理します。<a href="https://learn.microsoft.com/en-us/windows/win32/api/d3d12/nf-d3d12-id3d12commandqueue-signal" target="_blank" rel="noreferrer">キューのSignal</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/d3d12/nf-d3d12-id3d12commandqueue-wait" target="_blank" rel="noreferrer">キューのWait</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/d3d12/nf-d3d12-id3d12fence-signal" target="_blank" rel="noreferrer">CPUのSignal</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/d3d12/nf-d3d12-id3d12fence-seteventoncompletion" target="_blank" rel="noreferrer">SetEventOnCompletion</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/d3d12/nf-d3d12-id3d12fence-getcompletedvalue" target="_blank" rel="noreferrer">GetCompletedValue</a></p><p>フェンスには値を更新するキューを一つ決め、そのキューに積む通知の値を順に増やすと、値と作業の対応を追いやすくなります。たとえば <code>copyDone</code> の11と <code>drawDone</code> の24は、別々のキューの進み具合です。D3D12のフェンスは小さい値で更新することも可能です。二つのキューから同じフェンスへ通知すると、実行順によって新しい通知の値を古い値で上書きすることがあります。同じキューへ複数のCPUスレッドから提出する設計でも、値の割り当てと通知をキューに積む順序を揃えます。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/user-mode-heap-synchronization#fences" target="_blank" rel="noreferrer">Microsoftのフェンスの更新順とタイムライン</a></p><h2 id="コピーしたテクスチャを描画で使う" tabindex="-1">コピーしたテクスチャを描画で使う <a class="header-anchor" href="#コピーしたテクスチャを描画で使う" aria-label="Permalink to &quot;コピーしたテクスチャを描画で使う&quot;">​</a></h2><p>図では、最初にCOPYキューで使うDEFAULTヒープ上のテクスチャを <code>COMMON</code> で作ります。COPYのリストで転送先に使うと、<code>COPY_DEST</code> へ暗黙に昇格します。コピーを含む <code>ExecuteCommandLists</code> の処理が終わると、COPYで使ったテクスチャの状態は <code>COMMON</code> に戻ります。COPYが <code>copyDone</code> の11を通知し、DIRECTはその値を待ちます。その先のDIRECTのリストでは、テクスチャを <code>COMMON</code> から <code>PIXEL_SHADER_RESOURCE</code> に遷移させて描画できます。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/user-mode-heap-synchronization#multi-queue-resource-access" target="_blank" rel="noreferrer">Microsoftのキュー間のリソース利用規則</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/using-resource-barriers-to-synchronize-resource-states-in-direct3d-12#state-decay-to-common" target="_blank" rel="noreferrer">COMMONへの復帰条件</a></p><p>以下は、リストの記録を終えた後に提出側で行う処理の抜粋です。<code>check</code> は <code>HRESULT</code> の失敗を処理する関数を表します。</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">copyQueue-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ExecuteCommandLists</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">copyList);</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">check</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(copyQueue-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Signal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(copyDone, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">11</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">));</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">directQueue-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ExecuteCommandLists</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">independentList);</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">check</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(directQueue-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Wait</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(copyDone, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">11</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">));</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">directQueue-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ExecuteCommandLists</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">drawList);</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">check</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(directQueue-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Signal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(drawDone, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">24</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">));</span></span></code></pre></div><p>既にDIRECTやCOMPUTEで使ったテクスチャをCOPYへ渡す場合も、COPY側の最初のアクセス時には <code>COMMON</code> が必要です。最後の利用時に <code>COMMON</code> へ戻る条件を満たさなければ、渡す側で明示的に遷移します。DIRECTとCOMPUTEの間では、キューの種類が変わることだけを理由に <code>COMMON</code> へ戻す必要はありません。後続の用途に合う状態と、書き込んだ結果を次のキューが使える順序の両方を管理します。<a href="https://learn.microsoft.com/en-us/windows/win32/api/d3d12/ne-d3d12-d3d12_resource_states" target="_blank" rel="noreferrer">MicrosoftのD3D12_RESOURCE_STATES</a> · <a href="/study/graphics/optimization/d3d12-resource-barriers.html">D3D12のリソースバリア</a></p><p>たとえばCOMPUTEが <code>UNORDERED_ACCESS</code> のテクスチャに書き込む場合、COMPUTEの処理後に <code>Signal</code> を積みます。DIRECTでは <code>Wait</code> の後に <code>PIXEL_SHADER_RESOURCE</code> への遷移を記録し、描画で読みます。フェンスはキュー間の実行順を、遷移バリアは次のアクセスに必要な状態を表します。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/user-mode-heap-synchronization#multi-queue-resource-access" target="_blank" rel="noreferrer">Microsoftの複数キューにおける読み書きの規則</a></p><h2 id="使い終えた資源から回収する" tabindex="-1">使い終えた資源から回収する <a class="header-anchor" href="#使い終えた資源から回収する" aria-label="Permalink to &quot;使い終えた資源から回収する&quot;">​</a></h2><p>図でCOPYだけが読むアップロード領域は、<code>copyDone</code> の11に到達した時点で再利用できます。転送先テクスチャと描画が参照するディスクリプターは、DIRECTが使い終えるまで保持します。この描画が最後の参照なら <code>drawDone</code> の24が回収の目印になります。複数のキューが最後まで参照する資源では、それぞれの完了を確認するか、必要な待ちを集めたキューに回収用の通知を積みます。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/fence-based-resource-management" target="_blank" rel="noreferrer">Microsoftのフェンスによる資源管理</a> · <a href="/study/graphics/optimization/gpu-resource-lifetime.html">GPUリソースの寿命とフェンス</a></p><h2 id="待ちの位置を決め、実行の重なりを測る" tabindex="-1">待ちの位置を決め、実行の重なりを測る <a class="header-anchor" href="#待ちの位置を決め、実行の重なりを測る" aria-label="Permalink to &quot;待ちの位置を決め、実行の重なりを測る&quot;">​</a></h2><p>COPYが未到達の <code>drawDone = 24</code> を待ってから <code>copyDone = 11</code> を通知し、DIRECTも11を待ってから24を通知すると、両方のキューが先へ進めなくなります。リスト間の書き込みと読み取りの依存を並べ、各待ちが参照する通知まで、どのキューが進めるかを確かめます。図ではテクスチャに依存しない描画を <code>Wait</code> より前に置き、COPYの完了を待つ区間を短くできる構成にしています。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/user-mode-heap-synchronization" target="_blank" rel="noreferrer">Microsoftのマルチエンジン同期の例</a></p><p>コンピュート処理をCOMPUTEキューへ移し、DIRECTキューの描画と重ねる設計を<strong>非同期コンピュート</strong>と呼びます。重なる区間は、データの依存関係、GPUが同時に実行できる処理、メモリ帯域などの競合で変わります。同じシーンとハードウェアで、DIRECTだけに提出する場合と、COMPUTEに分ける場合を測ります。PIXのTiming Captureなどで、両方のキューの実行区間、待ちの位置、フレーム全体にかかった時間を比べます。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/user-mode-heap-synchronization#pipelined-compute-and-graphics-example" target="_blank" rel="noreferrer">Microsoftの非同期コンピュートの例</a> · <a href="https://devblogs.microsoft.com/pix/timing-captures-new/" target="_blank" rel="noreferrer">Microsoft PIXのTiming Captures</a></p><p>実践では二つのCPUワーカーが別々に記録したリストを、一つのDIRECTキューへ依存順に提出します。GPUのコピー結果をCPUで読み戻し、記録順と実行に必要な順序を追います。<a href="/study/practice/graphics/parallel-command-recording-observation.html">D3D12の並列記録を試す</a></p>`,22)])])}const u=i(r,[["render",o]]);export{E as __pageData,u as default};
